SECCOMP_IOCTL_NOTIF_RECV = 0xC0502100


def inspect_listener(fd):
    poll = select.poll()
    poll.register(fd, select.POLLIN | select.POLLPRI | select.POLLERR | select.POLLHUP)
    revents = 0
    for _, ev in poll.poll(0):
        revents |= ev
    os.set_blocking(fd, False)
    buf = bytearray(80)
    try:
        fcntl.ioctl(fd, SECCOMP_IOCTL_NOTIF_RECV, buf, True)
        nid, pid, flg, nr, arch, ip, a0, a1, a2, a3, a4, a5 = struct.unpack("<QIIiIQQQQQQQ", buf)
        return {
            "revents": revents,
            "pollin": bool(revents & select.POLLIN),
            "pollhup": bool(revents & select.POLLHUP),
            "notif": {
                "id": nid,
                "pid": pid,
                "flags": flg,
                "syscall_nr": nr,
                "arch": arch,
                "ip": ip,
                "args": [a0, a1, a2, a3, a4, a5],
            },
        }
    except OSError as exc:
        return {
            "revents": revents,
            "pollin": bool(revents & select.POLLIN),
            "pollhup": bool(revents & select.POLLHUP),
            "ioctl_errno": exc.errno,
        }

